# Harmonia Paper White
# generated by harmonia-terminal, do not edit

& {
  $e = [char]27

  try {
    if (Get-Module PSReadLine) {
      $rlVersion = (Get-Module PSReadLine).Version
      $colors = @{
        Default = "$e[39m"
        Comment = "$e[38;2;111;117;127m"
        Keyword = "$e[38;2;126;55;166m"
        String = "$e[38;2;17;101;76m"
        Number = "$e[38;2;123;80;11m"
        Operator = "$e[38;2;86;89;97m"
        Variable = "$e[38;2;13;99;100m"
        Parameter = "$e[38;2;23;97;109m"
        Command = "$e[38;2;52;87;157m"
        Type = "$e[38;2;36;90;153m"
        Member = "$e[38;2;59;63;72m"
        Emphasis = "$e[38;2;52;87;157m"
        Error = "$e[38;2;172;30;48m"
        ContinuationPrompt = "$e[38;2;118;118;118m"
        Selection = "$e[39;48;2;224;231;240m"
      }
      if ($rlVersion -ge [version]'2.1') {
        $colors.InlinePrediction = "$e[38;2;111;117;127m"
      }
      if ($rlVersion -ge [version]'2.2') {
        $colors.ListPrediction = "$e[38;2;52;87;157m"
        $colors.ListPredictionSelected = "$e[48;2;232;240;255m"
      }
      if ($rlVersion -ge [version]'2.3') {
        $colors.ListPredictionTooltip = "$e[38;2;111;117;127m"
      }
      Set-PSReadLineOption -Colors $colors -ErrorAction Stop
    }
  } catch {}

  try {
    if ($PSVersionTable.PSVersion -ge [version]'7.2') {
      $PSStyle.Formatting.TableHeader = "$e[1;38;2;36;90;153m"
      $PSStyle.Formatting.FormatAccent = "$e[1;38;2;36;90;153m"
      $PSStyle.Formatting.CustomTableHeaderLabel = "$e[3;38;2;36;90;153m"
      $PSStyle.Formatting.Error = "$e[38;2;172;30;48m"
      $PSStyle.Formatting.ErrorAccent = "$e[1;38;2;172;30;48m"
      $PSStyle.Formatting.Warning = "$e[38;2;131;76;0m"
      $PSStyle.Formatting.Verbose = "$e[38;2;28;93;139m"
      $PSStyle.Formatting.Debug = "$e[38;2;111;117;127m"
      $formatting = $PSStyle.Formatting.PSObject.Properties
      if ($formatting['FeedbackName']) { $PSStyle.Formatting.FeedbackName = "$e[38;2;52;87;157m" }
      if ($formatting['FeedbackText']) { $PSStyle.Formatting.FeedbackText = "$e[39m" }
      if ($formatting['FeedbackAction']) { $PSStyle.Formatting.FeedbackAction = "$e[38;2;17;101;76m" }
      $PSStyle.Progress.Style = "$e[38;2;255;255;255;48;2;74;111;184m"
      $PSStyle.FileInfo.Directory = "$e[1;38;2;52;87;157m"
      $PSStyle.FileInfo.SymbolicLink = "$e[38;2;13;99;100m"
      $PSStyle.FileInfo.Executable = "$e[38;2;17;101;76m"
      $PSStyle.FileInfo.Extension['.zip'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.tgz'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.gz'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.tar'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.nupkg'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.cab'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.7z'] = "$e[38;2;123;80;11m"
      $PSStyle.FileInfo.Extension['.ps1'] = "$e[38;2;126;55;166m"
      $PSStyle.FileInfo.Extension['.psd1'] = "$e[38;2;126;55;166m"
      $PSStyle.FileInfo.Extension['.psm1'] = "$e[38;2;126;55;166m"
      $PSStyle.FileInfo.Extension['.ps1xml'] = "$e[38;2;126;55;166m"
      $PSStyle.FileInfo.Extension['.js'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.jse'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.vbs'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.vbe'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.wsf'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.wsh'] = "$e[39m"
      $formatFile = Join-Path $PSScriptRoot 'harmonia.format.ps1xml'
      if (Test-Path $formatFile) { Update-FormatData -PrependPath $formatFile }
    }
